window.AUTH=window.AUTH||{};window.AUTH["89-1149"]={"d":"89-1149","id":"1990/89-1149","n":"Grogan v. Garner","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States, the Securities and Exchange","date":"","url":"https://www.justice.gov/osg/media/232926/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/coy-r-grogan-et-al-petitioners-v-frank-j-garnerjr","toa":false,"n":60}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep498/usrep498279/usrep498279.pdf","tr":false,"items":[{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"op":2,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Basic Inc. v. Levinson","cite":"485 U.S. 224","y":1988,"id":"1987/86-279","sc":1,"sum":"The Supreme Court held that there was no reason to artificially exclude merger conversations from the definition of materiality simply because they do not include specific prices.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Grogan v. Garner","cite":"806 F.2d 829","y":1986,"url":"https://www.courtlistener.com/c/F.2d/806/829/","op":1,"by":{"0":""}},{"t":"case","label":"Steadman v. SEC","cite":"450 U.S. 91","y":1981,"id":"1980/79-1266","sc":1,"op":1,"sum":"After an on-the-record hearing before an Administrative Law Judge and review by the Securities and Exchange Commission (SEC) in which the preponderance-of-the-evidence standard of proof was employed, the SEC held that petitioner had violated various antifraud provisions of the federal securities laws, and sanctions were imposed. Petitioner sought review in the Court of Appeals on the alleged ground, inter alia, that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Addington v. Texas","cite":"441 U.S. 418","y":1979,"id":"1978/77-5992","sc":1,"op":1,"sum":"The Court held that the standard of proof required in a civil case involving involuntary commitment to a mental health facility must be higher than a preponderance of the evidence, but that the “beyond a reasonable doubt” standard was not constitutionally required.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Santosky v. Kramer","cite":"455 U.S. 745","y":1982,"id":"1981/80-5889","sc":1,"sum":"Under New York law, the State may terminate, over parental objection, the rights of parents in their natural child upon a finding that the child is \"permanently neglected.\" The New York Family Court Act (§ 622) requires that only a \"fair preponderance of the evidence\" support that finding. Neglect proceedings were brought in Family Court to terminate petitioners' rights as natural parents in their three children. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Regan","cite":"232 U.S. 37","y":1914,"id":"scdb/1913-285","sc":1,"sum":"While in strictly criminal prosecutions the jury may not return ar verdict against the defendant unless the evidence establishes his guilt beyond a reasonable doubt, in civil actions it is the duty of the jury to resolve the issues of fact according to the reasonable preponderance of the evidence, and this although they may involve a penalized or criminal act.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"op":1,"sum":"1. A court of bankruptcy has jurisdiction by ancillary proceedings to enforce an order of discharge by enjoining the prosecution of suits brought against the debtor.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Sotelo","cite":"436 U.S. 268","y":1978,"id":"1977/76-1800","sc":1,"sum":"Respondents liability under § 6672 is nondischargeable in bankruptcy under § 17a (1) (e).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Kras","cite":"409 U.S. 434","y":1973,"id":"1972/71-749","sc":1,"op":1,"sum":"This case is not controlled by Boddie, supra. For here access to courts is not the only conceivable relief available to bankrupts; the filing-fee requirement does not deny an indigent the equal protection of the laws, since there is no constitutional right to obtain a discharge of one's debts in bankruptcy; the right to a discharge in bankruptcy is not a \"fundamental\" right demanding a compelling governmental …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Ron Pair Enterprises, Inc.","cite":"109 S. Ct. 1026","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Midlantic Nat'l Bank v. New Jersey Dep't of Environmental Protection","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Pennsylvania v. Davenport","cite":"110 S. Ct. 2126","y":1990,"id":"1989/89-156","sc":1,"sum":"The Code's language and structure demonstrate that restitution obligations constitute \"debts\" within the meaning of § 101(11) and are therefore dischargeable under Chapter 13.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Kelly v. Robinson","cite":"479 U.S. 36","y":1986,"id":"1986/85-1033","sc":1,"op":1,"sum":"Section 523(a)(7) preserves from discharge in Chapter 7 any condition a state criminal court imposes as part of a criminal sentence. Thus, restitution obligations, imposed as conditions of probation in state criminal proceedings, are not dischargeable.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Sweet v. Ritter Finance Co.","cite":"263 F. Supp. 540","y":1967,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./263/540/","op":1,"by":{"0":""}},{"t":"case","label":"Ames v. Moir","cite":"138 U.S. 306","y":1891,"id":"scdb/1890-113","sc":1,"sum":"“ Fraud” in the act of Congress, defining the debts from which a bankrupt is not relieved by a discharge in bankruptcy, means positive fraud, or fraud in fact, involving moral turpitude or intentional wrong: citing and afiirming previous decisions to the same point.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Fierman v. Lazarus","cite":"361 F. Supp. 477","y":1973,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./361/477/","op":1,"by":{"0":""}},{"t":"case","label":"Brown v. Buchanan","cite":"419 F. Supp. 199","y":1975,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./419/199/","op":1,"by":{"0":""}},{"t":"case","label":"SEC v. C.M. Joiner Leasing Corp.","cite":"320 U.S. 344","y":1943,"id":"scdb/1943-006","sc":1,"op":1,"by":{"0":""}},{"t":"case","label":"Lawrence v. CFTC","cite":"759 F.2d 767","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/759/767/","by":{"0":""}},{"t":"case","label":"Montana v. United States","cite":"440 U.S. 147","y":1979,"id":"1978/77-1134","sc":1,"sum":"The United States is collaterally estopped from challenging the prior judgment of the Montana Supreme Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","id":"1978/77-1305","sc":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Heiser v. Woodruff","cite":"327 U.S. 726","y":1946,"id":"scdb/1945-103","sc":1,"op":1,"sum":"1. Where, in a bankruptcy proceeding, allowance of a claim based upon a money judgment acquired against the bankrupt before the bankruptcy is objected to on the ground that the judgment was procured by fraud, but the issue of fraud has been litigated and decided between the claimant and the bankrupt before the bankruptcy and has since been litigated and decided between the claimant and the trustee in bankruptcy, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Fischer v. Pauline Oil & Gas Co.","cite":"309 U.S. 294","y":1940,"id":"scdb/1939-050","sc":1,"by":{"0":""}},{"t":"case","label":"Davis v. Friedlander","cite":"104 U.S. 570","y":1881,"id":"scdb/1881-072","sc":1,"sum":"Friedlander, Stich, &. Co., sued Kaufman, their debtor, in the law court of Memphis, taking out an attachment, which was levied, Nov. 30, 1866, upon-his real estate in that\" city. On different days in December, 1866, and-January, 1867, Davis and other creditors sued him in the chancery court, each taking out anattachment, which was promptly levied on the. same real estate. On the 14th of July, 1868, he was adjudged …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Combs v. Richardson","cite":"838 F.2d 112","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/838/112/","op":2,"by":{"0":""}},{"t":"case","label":"Klingman v. Levinson","cite":"831 F.2d 1292","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/831/1292/","op":1,"by":{"0":""}},{"t":"case","label":"Lovell v. Mixon","cite":"719 F.2d 1373","y":1983,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/719/1373/","op":1,"by":{"0":""}},{"t":"case","label":"Spilman v. Harley","cite":"656 F.2d 224","url":"https://www.courtlistener.com/c/F.2d/656/224/","op":1,"by":{"0":""}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"109 S. Ct. 1775","y":1989,"id":"1988/87-1167","sc":1,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Boddie v. Connecticut","cite":"401 U.S. 371","y":1971,"id":"1969/27","sc":1,"sum":"The Court reversed the District Court and held the fee requirement unconstitutional. In a majority opinion authored by Justice John M. Harlan, the Court recognized the importance of \"access to the courts\" for Boddie, as state court was the only method of obtaining a divorce in Connecticut.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Woodby v. INS","cite":"385 U.S. 276","y":1966,"id":"1966/40","sc":1,"sum":"No deportation order may be entered unless the Government proves by clear, unequivocal, and convincing evidence that the facts alleged as grounds for deportation are true.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"New York Times v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Chaunt v. United States","cite":"364 U.S. 350","y":1960,"id":"1960/22","sc":1,"sum":"The Court held that the Government did not meet its standard of proof required under the Immigration and Nationality Act to revoke an order of naturalization.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Schneiderman v. United States","cite":"320 U.S. 118","y":1943,"id":"scdb/1942-045","sc":1,"sum":"(1) That the evidence, which is reviewed in the opinion, fails to show with the requisite degree of certainty that during the period in question the defendant was not attached to the principles of the Constitution. P. 135. (2) Attachment to the principles of the Constitution is not necessarily incompatible with a desire to have it amended. P. 137. (3) Utterances of certain leaders of the party organizations in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Union Bank v. Blum","cite":"460 F.2d 197","y":1972,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/460/197/","op":2,"by":{"0":""}},{"t":"case","label":"First Nat'l Monetary Corp. v. Weinberger","cite":"819 F.2d 1334","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1334/","op":2,"by":{"0":""}},{"t":"case","label":"Vanston Bondholders Protective Comm. v. Green","cite":"329 U.S. 156","y":1946,"id":"scdb/1946-010","sc":1,"op":1,"sum":"In a reorganization proceeding under Chapter X of the Bankruptcy Act, claim was made under a covenant in a first mortgage indenture for interest on interest which had accrued after payments by the debtor corporation had been suspended by a court order in an equity receivership, which was succeeded by a reorganization proceeding under § 77B and later by the Chapter X proceeding. The corporation was insolvent; its …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Oriel v. Russell","cite":"278 U.S. 358","y":1929,"id":"scdb/1928-076","sc":1,"sum":"1. An order commanding a bankrupt to turn over to his trustee in bankruptcy books or property which he is charged with wilfully withholding but which he denies are within his possession or control, should be made only on clear and convincing evidence, exceeding a mere preponderance.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"L & S Enterprises Co. v. Great American Ins. Co.","cite":"454 F.2d 457","y":1971,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/454/457/","by":{"0":""}},{"t":"case","label":"Transitron Elec. Corp. v. Hughes Aircraft Co.","cite":"649 F.2d 871","y":1981,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/649/871/","by":{"0":""}},{"t":"case","label":"United States v. American Bell Tel. Co.","cite":"167 U.S. 224","y":1897,"id":"scdb/1896-198","sc":1,"sum":"If an application has been made for a patent for an invention, and the applicant has once called for action, he cannot be deprived of any benefits which flow from the ultimate action of the tribunal, although that tribunal may unnecessarily, negligently or even wantonly, if that supposition were admissible, delay its judgment.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Southern Dev. Co. v. Silva","cite":"125 U.S. 247","y":1888,"id":"scdb/1887-181","sc":1,"sum":"The general rule that when the answer of the defendant in a cause in equity is direct, positive, and unequivocal in its denial of the allegations in the bill, and an answer on.oath is not waived, the complainant will not be entitled +o a decree unless these denials are disproved by evidence of greater weight than the testimony of one witness, or by that of one witness with corroborating circumstances, applies when …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"0":""}},{"t":"usc","label":"31 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/31/3731","subs":["(c)"],"stext":{"head":"§3731. False claims procedure","paras":[[0,"(a) A subpena requiring the attendance of a witness at a trial or hearing conducted under section 3730 of this title may be served at any place in the United States."],[0,"(b) A civil action under section 3730 may not be brought—"],[1,"(1) more than 6 years after the date on which the violation of section 3729 is committed, or"],[1,"(2) more than 3 years after the date when facts material to the right of action are known or reasonably should have been known by the official of the United States charged with responsibility to act in the circumstances, but in no event more than 10 years after the date on which the violation is committed,"],[0,"whichever occurs last."],[0,"(c) If the Government elects to intervene and proceed with an action brought under 3730(b),1 the Government may file its own complaint or amend the complaint of a person who has brought an action under section 3730(b) to clarify or add detail to the claims in which the Government is intervening and to add any additional claims with respect to which the Government contends it is entitled to relief. For statute of limitations purposes, any such Government pleading shall relate back to the filing date of the complaint of the person who originally brought the action, to the extent that the claim of the Government arises out of the conduct, transactions, or occurrences set forth, or attempted to be set forth, in the prior complaint of that person."],[0,"(d) In any action brought under section 3730, the United States shall be required to prove all essential elements of the cause of action, including damages, by a preponderance of the evidence."],[0,"(e) Notwithstanding any other provision of law, the Federal Rules of Criminal Procedure, or the Federal Rules of Evidence, a final judgment rendered in favor of the United States in any criminal proceeding charging fraud or false statements, whether upon a verdict after trial or upon a plea of guilty or nolo contendere, shall estop the defendant from denying the essential elements of the offense in any action which involves the same transaction as in the criminal proceeding and which is brought under subsection (a) or (b) of section 3730."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3731?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3731. False claims procedure","tname":"Money and Finance","by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/11/1109","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","subs":["(i)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1821","url":"https://www.law.cornell.edu/uscode/text/12/1821","subs":["(k)"],"by":{"0":""}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","by":{"0":""}},{"t":"usc","label":"7 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/7/1","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1833a","url":"https://www.law.cornell.edu/uscode/text/12/1833a","subs":["(e)"],"stext":{"head":"§1833a. Civil penalties","paras":[[0,"(a) In general"],[0,"Whoever violates any provision of law to which this section is made applicable by subsection (c) shall be subject to a civil penalty in an amount assessed by the court in a civil action under this section."],[0,"(b) Maximum amount of penalty"],[0,"(1) Generally"],[1,"The amount of the civil penalty shall not exceed $1,000,000."],[0,"(2) Special rule for continuing violations"],[1,"In the case of a continuing violation, the amount of the civil penalty may exceed the amount described in paragraph (1) but may not exceed the lesser of $1,000,000 per day or $5,000,000."],[0,"(3) Special rule for violations creating gain or loss"],[1,"(A) If any person derives pecuniary gain from the violation, or if the violation results in pecuniary loss to a person other than the violator, the amount of the civil penalty may exceed the amounts described in paragraphs (1) and (2) but may not exceed the amount of such gain or loss."],[1,"(B) As used in this paragraph, the term \"person\" includes the Bank Insurance Fund, the Savings Association Insurance Fund, and after the merger of such funds, the Deposit Insurance Fund, and the National Credit Union Share Insurance Fund."],[0,"(c) Violations to which penalty is applicable"],[0,"This section applies to a violation of, or a conspiracy to violate—"],[1,"(1) section 215, 656, 657, 1005, 1006, 1007, 1014, or 1344 of title 18;"],[1,"(2) section 287, 1001, 1032,1 1341 or 1343 of title 18 affecting a federally insured financial institution; or"],[1,"(3) section 645(a) of title 15."],[0,"(d) Effective date"],[0,"This section shall apply to violations occurring on or after August 10, 1984."],[0,"(e) Attorney General to bring action"],[0,"A civil action to recover a civil penalty under this section shall be commenced by the Attorney General."],[0,"(f) Burden of proof"],[0,"In a civil action to recover a civil penalty under this section, the Attorney General must establish the right to recovery by a preponderance of the evidence."],[0,"(g) Administrative subpoenas"],[0,"(1) In general"],[1,"For the purpose of conducting a civil investigation in contemplation of a civil proceeding under this section, the Attorney General may—"],[2,"(A) administer oaths and affirmations;"],[2,"(B) take evidence; and"],[2,"(C) by subpoena, summon witnesses and require the production of any books, papers, correspondence, memoranda, or other records which the Attorney General deems relevant or material to the inquiry. Such subpoena may require the attendance of witnesses and the production of any such records from any place in the United States at any place in the United States designated by the Attorney General."],[0,"(2) Procedures applicable"],[1,"The same procedures and limitations as are provided with respect to civil investigative demands in subsections (g), (h), and (j) of section 1968 of title 18 apply with respect to a subpoena issued under this subsection. Process required by such subsections to be served upon the custodian shall be served on the Attorney General. Failure to comply with an order of the court to enforce such subpoena shall be punishable as contempt."],[0,"(3) Limitation"],[1,"In the case of a subpoena for which the return date is less than 5 days after the date of service, no person shall be found in contempt for failure to comply by the return date if such person files a petition under paragraph (2) not later than 5 days after the date of service."],[0,"(h) Statute of limitations"],[0,"A civil action under this section may not be commenced later than 10 years after the cause of action accrues."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1833a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1833a. Civil penalties","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§523. Exceptions to discharge","tname":"Bankruptcy","by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 35","url":"https://www.law.cornell.edu/uscode/text/11/35","subs":["(1976)"],"op":1,"tname":"Bankruptcy","by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 727","url":"https://www.law.cornell.edu/uscode/text/11/727","stext":{"head":"§727. Discharge","paras":[[0,"(a) The court shall grant the debtor a discharge, unless—"],[1,"(1) the debtor is not an individual;"],[1,"(2) the debtor, with intent to hinder, delay, or defraud a creditor or an officer of the estate charged with custody of property under this title, has transferred, removed, destroyed, mutilated, or concealed, or has permitted to be transferred, removed, destroyed, mutilated, or concealed—"],[2,"(A) property of the debtor, within one year before the date of the filing of the petition; or"],[2,"(B) property of the estate, after the date of the filing of the petition;"],[1,"(3) the debtor has concealed, destroyed, mutilated, falsified, or failed to keep or preserve any recorded information, including books, documents, records, and papers, from which the debtor's financial condition or business transactions might be ascertained, unless such act or failure to act was justified under all of the circumstances of the case;"],[1,"(4) the debtor knowingly and fraudulently, in or in connection with the case—"],[2,"(A) made a false oath or account;"],[2,"(B) presented or used a false claim;"],[2,"(C) gave, offered, received, or attempted to obtain money, property, or advantage, or a promise of money, property, or advantage, for acting or forbearing to act; or"],[2,"(D) withheld from an officer of the estate entitled to possession under this title, any recorded information, including books, documents, records, and papers, relating to the debtor's property or financial affairs;"],[1,"(5) the debtor has failed to explain satisfactorily, before determination of denial of discharge under this paragraph, any loss of assets or deficiency of assets to meet the debtor's liabilities;"],[1,"(6) the debtor has refused, in the case—"],[2,"(A) to obey any lawful order of the court, other than an order to respond to a material question or to testify;"],[2,"(B) on the ground of privilege against self-incrimination, to respond to a material question approved by the court or to testify, after the debtor has been granted immunity with respect to the matter concerning which such privilege was invoked; or"],[2,"(C) on a ground other than the properly invoked privilege against self-incrimination, to respond to a material question approved by the court or to testify;"],[1,"(7) the debtor has committed any act specified in paragraph (2), (3), (4), (5), or (6) of this subsection, on or within one year before the date of the filing of the petition, or during the case, in connection with another case, under this title or under the Bankruptcy Act, concerning an insider;"],[1,"(8) the debtor has been granted a discharge under this section, under section 1141 of this title, or under section 14, 371, or 476 of the Bankruptcy Act, in a case commenced within 8 years before the date of the filing of the petition;"],[1,"(9) the debtor has been granted a discharge under section 1228 or 1328 of this title, or under section 660 or 661 of the Bankruptcy Act, in a case commenced within six years before the date of the filing of the petition, unless payments under the plan in such case totaled at least—"],[2,"(A) 100 percent of the allowed unsecured claims in such case; or"],[2,"(B)(i) 70 percent of such claims; and"],[2,"(ii) the plan was proposed by the debtor in good faith, and was the debtor's best effort;"],[1,"(10) the court approves a written waiver of discharge executed by the debtor after the order for relief under this chapter;"],[1,"(11) after filing the petition, the debtor failed to complete an instructional course concerning personal financial management described in section 111, except that this paragraph shall not apply with respect to a debtor who is a person described in section 109(h)(4) or who resides in a district for which the United States trustee (or the bankruptcy administrator, if any) determines that the approved instructional courses are not adequate to service the additional individuals who would otherwise be required to complete such instructional courses under this section (The United States trustee (or the bankruptcy administrator, if any) who makes a determination described in this paragraph shall review such determination not later than 1 year after the date of such determination, and not less frequently than annually thereafter.); or"],[1,"(12) the court after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge finds that there is reasonable cause to believe that—"],[2,"(A) section 522(q)(1) may be applicable to the debtor; and"],[2,"(B) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B)."],[0,"(b) Except as provided in section 523 of this title, a discharge under subsection (a) of this section discharges the debtor from all debts that arose before the date of the order for relief under this chapter, and any liability on a claim that is determined under section 502 of this title as if such claim had arisen before the commencement of the case, whether or not a proof of claim based on any such debt or liability is filed under section 501 of this title, and whether or not a claim based on any such debt or liability is allowed under section 502 of this title."],[0,"(c)(1) The trustee, a creditor, or the United States trustee may object to the granting of a discharge under subsection (a) of this section."],[0,"(2) On request of a party in interest, the court may order the trustee to examine the acts and conduct of the debtor to determine whether a ground exists for denial of discharge."],[0,"(d) On request of the trustee, a creditor, or the United States trustee, and after notice and a hearing, the court shall revoke a discharge granted under subsection (a) of this section if—"],[1,"(1) such discharge was obtained through the fraud of the debtor, and the requesting party did not know of such fraud until after the granting of such discharge;"],[1,"(2) the debtor acquired property that is property of the estate, or became entitled to acquire property that would be property of the estate, and knowingly and fraudulently failed to report the acquisition of or entitlement to such property, or to deliver or surrender such property to the trustee;"],[1,"(3) the debtor committed an act specified in subsection (a)(6) of this section; or"],[1,"(4) the debtor has failed to explain satisfactorily—"],[2,"(A) a material misstatement in an audit referred to in section 586(f) of title 28; or"],[2,"(B) a failure to make available for inspection all necessary accounts, papers, documents, financial records, files, and all other papers, things, or property belonging to the debtor that are requested for an audit referred to in section 586(f) of title 28."],[0,"(e) The trustee, a creditor, or the United States trustee may request a revocation of a discharge—"],[1,"(1) under subsection (d)(1) of this section within one year after such discharge is granted; or"],[1,"(2) under subsection (d)(2) or (d)(3) of this section before the later of—"],[2,"(A) one year after the granting of such discharge; and"],[2,"(B) the date the case is closed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/727?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§727. Discharge","tname":"Bankruptcy","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 1320a-7a","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7a","stext":{"head":"§1320a–7a. Civil monetary penalties","paras":[[0,"(a) Improperly filed claims"],[0,"Any person (including an organization, agency, or other entity, but excluding a beneficiary, as defined in subsection (i)(5)) that—"],[1,"(1) knowingly presents or causes to be presented to an officer, employee, or agent of the United States, or of any department or agency thereof, or of any State agency (as defined in subsection (i)(1)), a claim (as defined in subsection (i)(2)) that the Secretary determines—"],[2,"(A) is for a medical or other item or service that the person knows or should know was not provided as claimed, including any person who engages in a pattern or practice of presenting or causing to be presented a claim for an item or service that is based on a code that the person knows or should know will result in a greater payment to the person than the code the person knows or should know is applicable to the item or service actually provided,"],[2,"(B) is for a medical or other item or service and the person knows or should know the claim is false or fraudulent,"],[2,"(C) is presented for a physician's service (or an item or service incident to a physician's service) by a person who knows or should know that the individual who furnished (or supervised the furnishing of) the service—"],[3,"(i) was not licensed as a physician,"],[3,"(ii) was licensed as a physician, but such license had been obtained through a misrepresentation of material fact (including cheating on an examination required for licensing), or"],[3,"(iii) represented to the patient at the time the service was furnished that the physician was certified in a medical specialty by a medical specialty board when the individual was not so certified,"],[2,"(D) is for a medical or other item or service furnished during a period in which the person was excluded from the Federal health care program (as defined in section 1320a–7b(f) of this title) under which the claim was made pursuant to Federal law.1"],[2,"(E) is for a pattern of medical or other items or services that a person knows or should know are not medically necessary;"],[1,"(2) knowingly presents or causes to be presented to any person a request for payment which is in violation of the terms of (A) an assignment under section 1395u(b)(3)(B)(ii) of this title, or (B) an agreement with a State agency (or other requirement of a State plan under subchapter XIX) not to charge a person for an item or service in excess of the amount permitted to be charged, or (C) an agreement to be a participating physician or supplier under section 1395u(h)(1) of this title, or (D) an agreement pursuant to section 1395cc(a)(1)(G) of this title;"],[1,"(3) knowingly gives or causes to be given to any person, with respect to coverage under subchapter XVIII of inpatient hospital services subject to the provisions of section 1395ww of this title, information that he knows or should know is false or misleading, and that could reasonably be expected to influence the decision when to discharge such person or another individual from the hospital;"],[1,"(4) in the case of a person who is not an organization, agency, or other entity, is excluded from participating in a program under subchapter XVIII or a State health care program in accordance with this subsection or under section 1320a–7 of this title and who, at the time of a violation of this subsection—"],[2,"(A) retains a direct or indirect ownership or control interest in an entity that is participating in a program under subchapter XVIII or a State health care program, and who knows or should know of the action constituting the basis for the exclusion; or"],[2,"(B) is an officer or managing employee (as defined in section 1320a–5(b) of this title) of such an entity;"],[1,"(5) offers to or transfers remuneration to any individual eligible for benefits under subchapter XVIII of this chapter, or under a State health care program (as defined in section 1320a–7(h) of this title) that such person knows or should know is likely to influence such individual to order or receive from a particular provider, practitioner, or supplier any item or service for which payment may be made, in whole or in part, under subchapter XVIII, or a State health care program (as so defined);"],[1,"(6) arranges or contracts (by employment or otherwise) with an individual or entity that the person knows or should know is excluded from participation in a Federal health care program (as defined in section 1320a–7b(f) of this title), for the provision of items or services for which payment may be made under such a program;"],[1,"(7) commits an act described in paragraph (1) or (2) of section 1320a–7b(b) of this title;"],[1,"(8) 2 knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim for payment for items and services furnished under a Federal health care program; or 3"],[1,"(9) 4 fails to grant timely access, upon reasonable request (as defined by the Secretary in regulations), to the Inspector General of the Department of Health and Human Services, for the purpose of audits, investigations, evaluations, or other statutory functions of the Inspector General of the Department of Health and Human Services;"],[1,"(8) 2 orders or prescribes a medical or other item or service during a period in which the person was excluded from a Federal health care program (as so defined), in the case where the person knows or should know that a claim for such medical or other item or service will be made under such a program;"],[1,"(9) 4 knowingly makes or causes to be made any false statement, omission, or misrepresentation of a material fact in any application, bid, or contract to participate or enroll as a provider of services or a supplier under a Federal health care program (as so defined), including Medicare Advantage organizations under part C of subchapter XVIII, prescription drug plan sponsors under part D of subchapter XVIII, medicaid managed care organizations under subchapter XIX, and entities that apply to participate as providers of services or suppliers in such managed care organizations and such plans; 5"],[1,"(10) knows of an overpayment (as defined in paragraph (4) of section 1320a–7k(d) of this title) and does not report and return the overpayment in accordance with such section;"],[0,"shall be subject, in addition to any other penalties that may be prescribed by law, to a civil money penalty of not more than $20,000 for each item or service (or, in cases under paragraph (3), $30,000 for each individual with respect to whom false or misleading information was given; in cases under paragraph (4), $20,000 for each day the prohibited relationship occurs; in cases under paragraph (7), $100,000 for each such act,6 in cases under paragraph (8),7 $100,000 for each false record or statement,6 or 3 in cases under paragraph (9),8 $15,000 for each day of the failure described in such paragraph); 9 or in cases under paragraph (9),10 $100,000 for each false statement or misrepresentation of a material fact). In addition, such a person shall be subject to an assessment of not more than 3 times the amount claimed for each such item or service in lieu of damages sustained by the United States or a State agency because of such claim (or, in cases under paragraph (7), damages of not more than 3 times the total amount of remuneration offered, paid, solicited, or received, without regard to whether a portion of such remuneration was offered, paid, solicited, or received for a lawful purpose; or in cases under paragraph (9), an assessment of not more than 3 times the total amount claimed for each item or service for which payment was made based upon the application containing the false statement or misrepresentation of a material fact). In addition the Secretary may make a determination in the same proceeding to exclude the person from participation in the Federal health care programs (as defined in section 1320a–7b(f)(1) of this title) and to direct the appropriate State agency to exclude the person from participation in any State health care program."],[0,"(b) Payments to induce reduction or limitation of services"],[0,"(1) If a hospital or a critical access hospital knowingly makes a payment, directly or indirectly, to a physician as an inducement to reduce or limit medically necessary services provided with respect to individuals who—"],[1,"(A) are entitled to benefits under part A or part B of subchapter XVIII or to medical assistance under a State plan approved under subchapter XIX, and"],[1,"(B) are under the direct care of the physician,"],[0,"the hospital or a critical access hospital shall be subject, in addition to any other penalties that may be prescribed by law, to a civil money penalty of not more than $5,000 for each such individual with respect to whom the payment is made."],[0,"(2) Any physician who knowingly accepts receipt of a payment described in paragraph (1) shall be subject, in addition to any other penalties that may be prescribed by law, to a civil money penalty of not more than $5,000 for each individual described in such paragraph with respect to whom the payment is made."],[0,"(3)(A) Any physician who executes a document described in subparagraph (B) with respect to an individual knowing that all of the requirements referred to in such subparagraph are not met with respect to the individual shall be subject to a civil monetary penalty of not more than the greater of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-7a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1320a–7a. Civil monetary penalties","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"26 U.S.C. § 6663","url":"https://www.law.cornell.edu/uscode/text/26/6663","subs":["(b)"],"by":{"0":""}},{"t":"usc","label":"18 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/18/152","by":{"0":""}}]};